-- Keep the landed comments migration immutable while correcting the first-party
-- template's public projection and depth presentation.
UPDATE block_definitions
SET template = '<section id="comments" class="stratum-comments"><h2 class="stratum-comments-title">Comments ({{ .Context.CommentsCount }})</h2><div id="comment-list">{{ if .Context.Comments }}{{ range .Context.Comments }}<article class="stratum-comment comment-depth-{{ .Depth }}" id="comment-{{ .ID }}"><header class="stratum-comment-header"><span class="stratum-comment-author">{{ .AuthorName }}</span> <time datetime="{{ .CreatedISO }}">{{ .CreatedAt }}</time>{{ if .ParentID }} <a href="#comment-{{ .ParentID }}">in reply</a>{{ end }}</header><div class="stratum-comment-body">{{ .Body }}</div></article>{{ end }}{{ else }}<p class="stratum-comments-empty">No comments yet.</p>{{ end }}</div>{{ if .Context.CommentsEnabled }}<form id="comment-form" method="post" action="/comments" class="stratum-comment-form" data-on:submit__prevent="@post(''/comments'', {contentType: ''form''})"><input type="hidden" name="entry_id" value="{{ .Context.CommentsEntryID }}"><input type="hidden" name="parent_id" value=""><div id="comment-form-errors"></div><p><label>Name <input name="author_name" required maxlength="100"></label></p><p><label>Email <input name="author_email" type="email" required maxlength="254"></label></p><p><label>Website <input name="author_url" type="url" maxlength="2048"></label></p><p class="stratum-comment-honeypot"><label>Leave empty <input name="website_confirm" autocomplete="off"></label></p><p><label>Comment <textarea name="body" required maxlength="5000"></textarea></label></p><p><button type="submit">Post Comment</button></p><div id="comment-submit-status"></div></form>{{ else }}<p class="stratum-comments-disabled">Comments are closed.</p>{{ end }}</section>',
    styles = '.stratum-comments{margin-top:var(--st-space-xl)}.stratum-comment{border-top:1px solid var(--st-color-border);padding:var(--st-space-md) 0}.stratum-comment-body{white-space:pre-wrap;word-wrap:break-word}.comment-depth-1{margin-left:1rem}.comment-depth-2{margin-left:2rem}.stratum-comment-honeypot{display:none}'
WHERE namespace = 'core' AND name = 'comments' AND version = 1;
